    "Bijna! Nog één verdachte staat verkeerd. {0} van de {1} staan al goed.": "దాదాపు! ఇంకా ఒకరు తప్పు చోట ఉన్నారు. {1} మందిలో {0} {0|one:వ్యక్తి|other:మంది} ఇప్పటికే సరైన చోట ఉన్నారు.",
    "{0} verdachten staan verkeerd, {1} staan goed. Gebruik een hint als je vastzit.": "{0} {0|one:వ్యక్తి|other:మంది} తప్పు చోట, {1} {1|one:వ్యక్తి|other:మంది} సరైన చోట ఉన్నారు. ముందుకు సాగకపోతే సూచన వాడండి.",
