    "Kruisje: tik een vakje waar de gekozen verdachte niet kan staan. Nog eens tikken haalt het kruisje weg.": "ఇంటూ: ఎంచుకున్న వ్యక్తి ఉండలేని గడిని నొక్కండి. మళ్లీ నొక్కితే ఇంటూ గుర్తు పోతుంది.",
