    "Over een uur is het al morgen. De zaak van vandaag staat nog klaar.": "గంట తర్వాత అప్పటికే రేపు అవుతుంది. ఈరోజు కేసు ఇంకా ఎదురుచూస్తోంది.",
    "De dossiers wachten op je. Ik stuur je geen herinneringen meer.": "ఫైళ్లు మీ కోసం ఎదురుచూస్తాయి. ఇక నేను రిమైండర్లు పంపను.",
    "De zaak van vandaag heet “{0}”. Een paar minuten, meer vraag ik niet.": "ఈరోజు కేసు పేరు “{0}”. కొన్ని నిమిషాలు చాలు, అంతకు మించి అడగను.",
    "Nieuw dossier: “{0}”. Plaats delict: {1}.": "కొత్త ఫైలు: “{0}”. నేరం జరిగిన చోటు: {1}.",
    "“{0}” ligt klaar. Een handvol verdachten, één waarheid. Kijk je even mee?": "“{0}” సిద్ధంగా ఉంది. కొద్దిమంది అనుమానితులు, ఒకే నిజం. ఓసారి చూస్తారా?",
    "De koffie staat klaar, het dossier ook: “{0}”.": "కాఫీ సిద్ధం, ఫైలు కూడా: “{0}”.",
    "Ik heb een zaak voor je: “{0}”. De vraag is kort: wie was waar?": "మీ కోసం ఒక కేసు ఉంది: “{0}”. ప్రశ్న చిన్నది: ఎవరు ఎక్కడ ఉన్నారు?",
    "{0} · “{1}”. Ik ben benieuwd wat jij ziet.": "{0} · “{1}”. మీరు ఏం గమనిస్తారో చూడాలని ఉంది.",
    "Het archief loopt niet weg. Vandaag ligt “{0}” klaar, als je zin hebt.": "ఆర్కైవ్ ఎక్కడికీ పారిపోదు. ఈరోజు “{0}” సిద్ధంగా ఉంది, మీకు ఆసక్తి ఉంటే.",
    "Een rustige dag op het bureau. “{0}” wacht geduldig op een frisse blik.": "ఆఫీసులో ప్రశాంతమైన రోజు. “{0}” కొత్త చూపు కోసం ఓపికగా ఎదురుచూస్తోంది.",
    "Geen haast. Als het uitkomt: “{0}” ligt bovenop de stapel.": "తొందర లేదు. వీలైనప్పుడు: “{0}” కుప్పలో అన్నింటికంటే పైన ఉంది.",
    "Ik heb je dossierkast netjes bijgehouden. Bovenop vandaag: “{0}”.": "మీ ఫైళ్ల అలమరను నేను చక్కగా సర్దిపెట్టాను. ఈరోజు పైన: “{0}”.",
    "Voor een kort moment tussendoor: “{0}”. Drie minuten en een kop thee.": "కాస్త తీరిక దొరికినప్పుడు: “{0}”. మూడు నిమిషాలు, ఒక కప్పు టీ.",
    "Je streak staat op {0} dagen. De zaak van vandaag ligt nog open: “{1}”.": "మీ స్ట్రీక్ {0} రోజులకు చేరింది. ఈరోజు కేసు ఇంకా తెరిచే ఉంది: “{1}”.",
    "{0} dagen op rij. Eén zaak vanavond en het worden er {1}.": "వరుసగా {0} రోజులు. ఈ రాత్రి ఒక కేసు, అవి {1} అవుతాయి.",
    "Nog een kort verhoor voor het slapengaan? “{0}” houdt je streak van {1} dagen heel.": "నిద్రకు ముందు ఒక చిన్న విచారణ? “{0}” మీ {1} రోజుల స్ట్రీక్‌ను నిలబెడుతుంది.",
    "🔥 {0} dagen. Het vuur brandt nog; één zaak houdt het aan.": "🔥 {0} రోజులు. మంట ఇంకా వెలుగుతోంది; ఒక కేసు దాన్ని ఆరిపోనివ్వదు.",
    "Om middernacht sluit het dossier van vandaag. Tijd genoeg voor “{0}” en dag {1} van je streak.": "అర్ధరాత్రికి ఈరోజు ఫైలు మూసుకుంటుంది. “{0}”కి, మీ స్ట్రీక్‌లో {1}వ రోజుకి కావలసినంత సమయం ఉంది.",
    "Rustig avondwerk: “{0}”. Daarmee komt je streak op {1} dagen.": "సాయంత్రపు ప్రశాంతమైన పని: “{0}”. దీంతో మీ స్ట్రీక్ {1} రోజులకు చేరుతుంది.",
