      "pos": "మూల రెండు గోడలకు తగులుతుంది, \"గోడకు ఆనుకుని\" ఒక్క గోడకు, \"మధ్యలో\" ఏ గోడకూ తగలదు.",
      "room-pos": "ఆ గదిలో ఏ మూల గడులు, గోడ గడులు ఇంకా ఖాళీగా ఉన్నాయో చూడండి. వస్తువులు తరచూ వాటిలో కొన్నింటిని ఆక్రమిస్తాయి.",
      "room-with": "\"మొక్క ఉన్న గది\"లో వేరే వస్తువులు కూడా ఉండవచ్చు. ముందు మొక్కను వెతకండి.",
