      "లాబీలో ఏటా జరిగే ముసుగుల నృత్యం. అందరూ ముసుగులు వేసుకున్నారు, ఎవరి పక్కన ఎవరు నిలబడ్డారో ఎవరికీ తెలియదు.",
      "అర్ధరాత్రి ముసుగులు తొలగుతాయి. అందరూ నవ్వడం లేదు.",
