      "వియన్నా, మిలాన్, లండన్. బృందం సెట్టింగ్ మొత్తంతో ప్రయాణిస్తుంది, ఇబ్బందులూ వెంటే వస్తాయి.",
      "చివరి నగరం తర్వాత సెట్టింగ్ పారిస్‌కు తిరిగి వెళ్తుంది. బృందం కూడా, ఒక్కరు తప్ప.",
