      "హాలులో అందరికంటే చివరగా వాన్ డామ్ లేస్తాడు. ఒక్కసారి చప్పట్లు కొట్టి, మెట్లు దిగి పారిస్ రాత్రిలోకి నడుచుకుంటూ వెళ్తాడు.",
