      "పైన డాబా మీద ఖగోళవేత్త జహ్రా తదుపరి ప్రయాణానికి దారిని నక్షత్రాల్లో చదువుతోంది. ఆకాశం నిర్మలంగా ఉంది, సత్రం నిద్రపోతోంది. అక్కడ ఉండకూడని ఒక వెలుగు ఆమెకు కనిపిస్తుంది.",
